/** The sheet's pools as the screen reads them, in the order they were added. */
public class RespondWithPools {
    public void respond(@Val Pools pools, ObjectResponse<List<PoolResponse>> response) {
        response.send(pools.list().stream().map(PoolResponse::from).toList());
    }
}
