package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.sql.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Rounding;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingRepository {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public SettingRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's settings: the dated ones in force on its today (and every value recorded), its policy date, its period numbering from date and its roles, by user name. */
    public Settings find(String sheetId) {
        List<UserRole> roles = jdbc.query("SELECT sheet_id, user_name, role FROM user_role WHERE sheet_id = ?"
                + " ORDER BY user_name", (rs, n) -> new UserRole(rs.getString("sheet_id"), rs.getString("user_name"),
                        Role.valueOf(rs.getString("role"))), sheetId);
        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, n) -> rs.getDate("today"), sheetId);
        LocalDate today = found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
        DatedSettings dated = dated(sheetId);
        return new Settings(sheetId, dated.clerkLimitOn(today), dated.floorOn(today), dated.termsOn(today),
                dated.gradeTermsOn(today), dated.latePctOn(today), policyDate(sheetId), periodNumberingFrom(sheetId), entryDate(sheetId),
                dated.capOn(today), dated.proofThresholdOn(today), roles, dated, permissions(sheetId), graceDays(sheetId),
                today, delegations(sheetId));
    }

    /** The sheet's dated settings: every value recorded, by key and from-date. */
    public DatedSettings dated(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> values = new LinkedHashMap<>();
        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_from WHERE sheet_id = ?"
                + " ORDER BY setting_key, from_date", (rs) -> {
                    values.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
                            .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value"));
                }, sheetId);
        return new DatedSettings(values);
    }

    /** Record the key's value from the date (null: blank), replacing any value already recorded from that date. */
    public void saveDated(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("DELETE FROM setting_from WHERE sheet_id = ? AND setting_key = ? AND from_date = ?",
                sheetId, key, Date.valueOf(from));
        jdbc.update("INSERT INTO setting_from (sheet_id, setting_key, from_date, setting_value) VALUES (?, ?, ?, ?)",
                sheetId, key, Date.valueOf(from), value);
    }

    /** The sheet's rounding policy date as set (null: blank, the sheet's today). */
    public LocalDate policyDate(String sheetId) {
        List<Date> date = jdbc.query("SELECT policy_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("policy_date"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** How the sheet rounds the given claims' live figures on the given today: by its policy date (blank: today). */
    public Rounding rounding(String sheetId, LocalDate today, List<Claim> claims) {
        LocalDate policyDate = policyDate(sheetId);
        return Rounding.of(policyDate == null ? today : policyDate, claims);
    }

    /** Set the sheet's rounding policy date (null: blank, the sheet's today). */
    public void savePolicyDate(String sheetId, LocalDate policyDate) {
        jdbc.update("UPDATE sheet SET policy_date = ? WHERE id = ?", policyDate == null ? null : Date.valueOf(policyDate), sheetId);
    }

    /** The sheet's period numbering from date (null: blank, off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        List<Date> date = jdbc.query("SELECT period_numbering_from FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("period_numbering_from"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** Set the sheet's period numbering from date (null: blank, off). */
    public void savePeriodNumberingFrom(String sheetId, LocalDate from) {
        jdbc.update("UPDATE sheet SET period_numbering_from = ? WHERE id = ?", from == null ? null : Date.valueOf(from), sheetId);
    }

    /** The sheet's entry date (null: blank, off). */
    public LocalDate entryDate(String sheetId) {
        List<Date> date = jdbc.query("SELECT entry_date FROM sheet WHERE id = ?",
                (rs, n) -> rs.getDate("entry_date"), sheetId);
        return date.isEmpty() || date.get(0) == null ? null : date.get(0).toLocalDate();
    }

    /** Set the sheet's entry date (null: blank, off). */
    public void saveEntryDate(String sheetId, LocalDate entryDate) {
        jdbc.update("UPDATE sheet SET entry_date = ? WHERE id = ?", entryDate == null ? null : Date.valueOf(entryDate), sheetId);
    }

    /** The sheet's grace days (null: blank, off). */
    public Integer graceDays(String sheetId) {
        List<Integer> days = jdbc.query("SELECT grace_days FROM sheet WHERE id = ?",
                (rs, n) -> (Integer) rs.getObject("grace_days", Integer.class), sheetId);
        return days.isEmpty() ? null : days.get(0);
    }

    /** Set the sheet's grace days (null: blank, off). */
    public void saveGraceDays(String sheetId, Integer days) {
        jdbc.update("UPDATE sheet SET grace_days = ? WHERE id = ?", days, sheetId);
    }

    /** The sheet's permission matrix: the roles set for each action, as shown (an action with none keeps the standing rule). */
    public Permissions permissions(String sheetId) {
        Map<String, String> set = new LinkedHashMap<>();
        jdbc.query("SELECT action, roles FROM permission WHERE sheet_id = ?", (rs) -> {
            set.put(rs.getString("action"), rs.getString("roles"));
        }, sheetId);
        return new Permissions(set);
    }

    /** Set the roles allowed the action on the sheet ("": blank, back to the standing rule). */
    public void savePermission(String sheetId, String action, String roles) {
        jdbc.update("DELETE FROM permission WHERE sheet_id = ? AND action = ?", sheetId, action);
        if (!roles.isEmpty()) {
            jdbc.update("INSERT INTO permission (sheet_id, action, roles) VALUES (?, ?, ?)", sheetId, action, roles);
        }
    }

    /** The steward role delegated on the sheet, in the order made. */
    public List<Delegation> delegations(String sheetId) {
        return jdbc.query("SELECT sheet_id, user_name, from_date, to_date, by_user FROM delegation WHERE sheet_id = ?"
                + " ORDER BY id", (rs, n) -> new Delegation(rs.getString("sheet_id"), rs.getString("user_name"),
                        rs.getDate("from_date").toLocalDate(), rs.getDate("to_date").toLocalDate(), rs.getString("by_user")),
                sheetId);
    }

    /** The steward who delegated the role to the user name by the latest delegation in force on the sheet's today, else null. */
    public String delegatorOf(String sheetId, String user) {
        List<String> found = jdbc.query("SELECT d.by_user FROM delegation d JOIN sheet s ON s.id = d.sheet_id"
                + " WHERE d.sheet_id = ? AND d.user_name = ? AND s.today BETWEEN d.from_date AND d.to_date"
                + " ORDER BY d.id DESC LIMIT 1", (rs, n) -> rs.getString("by_user"), sheetId, user);
        return found.isEmpty() ? null : found.get(0);
    }

    /** Record the steward role delegated. */
    public void saveDelegation(Delegation delegation) {
        jdbc.update("INSERT INTO delegation (sheet_id, user_name, from_date, to_date, by_user) VALUES (?, ?, ?, ?, ?)",
                delegation.sheetId(), delegation.user(), Date.valueOf(delegation.from()), Date.valueOf(delegation.to()),
                delegation.by());
    }

    /** Give the user name its role on the sheet, replacing any it had. */
    public void saveRole(UserRole role) {
        int updated = jdbc.update("UPDATE user_role SET role = ? WHERE sheet_id = ? AND user_name = ?",
                role.role().name(), role.sheetId(), role.user());
        if (updated == 0) {
            jdbc.update("INSERT INTO user_role (sheet_id, user_name, role) VALUES (?, ?, ?)",
                    role.sheetId(), role.user(), role.role().name());
        }
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.Size;
import java.util.Map;

/**
 * The settings as the form submits them; a setting left out (null) is left as it is. The clerk limit has two
 * decimals at most (blank: no limit); the floor has two decimals at most (blank: back to 1.00); the terms are
 * whole days, 0 or more (blank: back to 14); the late percent has two decimals at most (blank: back to 0.00); the policy date is
 * yyyy-MM-dd (blank: the sheet's today); the period numbering from date is yyyy-MM-dd (blank: off); the entry date is yyyy-MM-dd (blank: off); the cap has two decimals at most (blank: no cap); the proof threshold has two decimals at most (blank: none); the note threshold has two decimals at most (blank: none). The grade terms are
 * whole days, 0 or more, by grade, each only for a grade it carries (blank: none of its own, the sheet's terms).
 * The clerk limit, floor, terms, late percent, cap, proof threshold, note threshold and each grade's terms are recorded from their from-date, yyyy-MM-dd
 * (left out or blank: the sheet's today). The permissions are, by action (open, settle, void, reassign, close, reopen),
 * the roles allowed it, comma separated (blank: the standing rule); they are not dated. The grace days are whole days,
 * 0 or more (blank: off); they are not dated. The grade grace days are whole days, 0 or more, by grade, each only for a
 * grade it carries (blank: none), recorded from their from-date by grade (left out or blank: the sheet's today). The grade
 * proof thresholds have two decimals at most, by grade, each only for a grade it carries (blank: none, the sheet's), recorded
 * from their from-date by grade (left out or blank: the sheet's today).
 */
public record SettingsRequest(@Size(max = 30) String clerkLimit, @Size(max = 30) String floor, @Size(max = 30) String terms,
        @Size(max = 30) String latePct, @Size(max = 30) String policyDate, @Size(max = 30) String periodNumberingFrom, @Size(max = 30) String entryDate, @Size(max = 30) String cap,
        @Size(max = 30) String proofThreshold, @Size(max = 30) String noteThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTerms,
        @Size(max = 30) String clerkLimitFrom, @Size(max = 30) String floorFrom, @Size(max = 30) String termsFrom,
        @Size(max = 30) String latePctFrom, @Size(max = 30) String capFrom, @Size(max = 30) String proofThresholdFrom,
        @Size(max = 30) String noteThresholdFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeTermsFrom,
        @Size(max = 10) Map<String, @Size(max = 100) String> permissions, @Size(max = 30) String graceDays,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeGrace,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeGraceFrom,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeProofThreshold,
        @Size(max = 10) Map<String, @Size(max = 30) String> gradeProofThresholdFrom) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * The settings as the screen reads them: the clerk limit (null: no limit), the floor, the terms in days, the terms set for
 * each grade that has its own (by grade), the late percent, the policy date ("": blank, the sheet's today), the period
 * numbering from date ("": off), the entry date ("": off), the cap ("": none), the proof threshold ("": none), the note threshold ("": none) — the dated ones as in force on the sheet's today — each role given,
 * by user name, the permission matrix (by action, the roles allowed it; "": blank, the standing rule), and every dated value recorded, by key, oldest from-date first (value "": blank), the grace days ("": off) and the steward role delegated, in the order made.
 */
public record SettingsResponse(String clerkLimit, String floor, int terms, Map<String, Integer> gradeTerms, String latePct, String policyDate, String periodNumberingFrom, String entryDate, String cap, String proofThreshold, String noteThreshold, List<RoleResponse> roles,
        Map<String, List<FromValueResponse>> history, Map<String, String> permissions, String graceDays,
        List<DelegationResponse> delegations) {

    public record RoleResponse(String user, String role) {
    }

    public record DelegationResponse(String user, String from, String to, String by) {
    }

    public record FromValueResponse(String from, String value) {
    }

    public static SettingsResponse from(Settings settings) {
        BigDecimal noteThreshold = settings.dated().noteThresholdOn(settings.today());
        Map<String, List<FromValueResponse>> history = new LinkedHashMap<>();
        settings.dated().history().forEach((key, values) -> history.put(key, values.stream()
                .map((v) -> new FromValueResponse(v.from().toString(), v.value() == null ? "" : v.value())).toList()));
        return new SettingsResponse(
                settings.clerkLimit() == null ? null : settings.clerkLimit().toPlainString(),
                settings.floor().toPlainString(),
                settings.terms(),
                settings.gradeTerms(),
                settings.latePct().toPlainString(),
                settings.policyDate() == null ? "" : settings.policyDate().toString(),
                settings.periodNumberingFrom() == null ? "" : settings.periodNumberingFrom().toString(),
                settings.entryDate() == null ? "" : settings.entryDate().toString(),
                settings.cap() == null ? "" : settings.cap().toPlainString(),
                settings.proofThreshold() == null ? "" : settings.proofThreshold().toPlainString(),
                noteThreshold == null ? "" : noteThreshold.toPlainString(),
                settings.roles().stream().map((r) -> new RoleResponse(r.user(), r.role().label())).toList(),
                history,
                settings.permissions().entries(),
                settings.graceDays() == null ? "" : settings.graceDays().toString(),
                settings.delegations().stream().map((d) -> new DelegationResponse(d.user(), d.from().toString(),
                        d.to().toString(), d.by())).toList());
    }
}
# Set the sheet's clerk limit (blank: no limit), its floor (blank: 1.00) and its terms in days (blank: 14) and each grade's own terms in days (blank: none, the sheet's terms) and its late percent (blank: 0.00) and its policy date (blank: the sheet's today) and its period numbering from date (blank: off) and its entry date (blank: off) and its cap (blank: none) and its proof threshold (blank: none) and each grade's proof threshold (blank: none, the sheet's) and its note threshold (blank: none) and its permission matrix (by action, the roles allowed it, comma separated; blank: the standing rule) and its grace days (blank: off) and each grade's grace days (blank: none), each only when the request carries it;
# a value that is negative or has more than two decimals (terms: not whole days) is refused (400). A floor, late percent, grade grace, policy date or cap moves the dues (terms do not: a claim's due-by is fixed when it is created), so the
# figures it moved are recorded after it.
